852	/// Per-request media content-part counts, carried to the metrics annotation.
853	/// Derived from `multi_modal_data`, so independent of the `mm-routing` feature.
854	#[derive(Debug, Clone, Copy, Default)]
855	pub struct MultimodalCounts {
856	    pub image: usize,
857	    pub video: usize,
858	    pub audio: usize,
859	}
860	
861	impl MultimodalCounts {
862	    /// Count `image_url` / `video_url` / `audio_url` parts (vec length per modality).
863	    fn from_preprocessed(request: &PreprocessedRequest) -> Self {
864	        let count = |key: &str| {
865	            request
866	                .multi_modal_data
867	                .as_ref()
868	                .and_then(|m| m.get(key))
869	                .map_or(0, |v| v.len())
870	        };
871	        Self {
872	            image: count("image_url"),
873	            video: count("video_url"),
874	            audio: count("audio_url"),
875	        }
876	    }
877	}
878	
879	#[cfg(feature = "mm-routing")]
880	fn checked_add_image_tokens(total: Option<usize>, next: usize) -> Option<usize> {
881	    total?.checked_add(next)
882	}
883	
884	#[cfg(feature = "mm-routing")]
885	fn has_image_token_processor_override(value: Option<&serde_json::Value>) -> bool {
886	    value.is_some_and(|value| match value {
887	        serde_json::Value::Null => false,
888	        serde_json::Value::Object(map) => !map.is_empty(),
889	        // The schema expects an object. Fail closed for every other JSON shape
890	        // because its processor semantics are unknown here.
891	        _ => true,
892	    })
893	}
894	
895	#[cfg(feature = "mm-routing")]
896	fn exact_mm_routing_preconditions_met(
897	    has_user_uuid: bool,
898	    resolved_image_count: usize,
899	    total_image_count: usize,
900	    has_processor_override: bool,
901	) -> bool {
902	    // Processor kwargs participate in backend feature hashing and can change
903	    // prompt expansion. Until the frontend reproduces those transformations,
904	    // exact routing must fail closed so router and worker cache keys agree.
905	    !has_user_uuid && !has_processor_override && resolved_image_count == total_image_count
906	}
907	
908	#[cfg(feature = "mm-routing")]
909	fn aggregate_image_tokens(
910	    image_tokens: Option<usize>,
911	    resolved_image_count: usize,
912	    total_image_count: usize,
913	    has_processor_override: bool,
914	) -> Option<usize> {
915	    if total_image_count == 0 || has_processor_override || resolved_image_count != total_image_count
916	    {
917	        return None;
918	    }
919	
920	    image_tokens
921	}
922	
923	/// Derive the model's local directory from the MDC. The directory is the
924	/// parent of `config.json` (which lives in `mdc.model_info` as `HfConfigJson`)
925	/// and contains the other artifacts MM-aware routing reads at startup
926	/// (`tokenizer.json`, `processor_config.json`, `preprocessor_config.json`).
927	/// Returns `None` for cards built from non-disk sources.
928	#[cfg(feature = "mm-routing")]
929	fn mdc_model_dir(mdc: &ModelDeploymentCard) -> Option<std::path::PathBuf> {
930	    let ModelInfoType::HfConfigJson(cf) = mdc.model_info.as_ref()?;
931	    cf.path()?.parent().map(std::path::PathBuf::from)
932	}
933	
934	/// Shared SSRF-aware `MediaFetcher` + `reqwest::Client` for the dim-fetch
935	/// path used by MM-aware routing and image-token metrics. Inherits the same
936	/// policy contract as the frontend-decode path (`MediaLoader`): blocklist DNS
937	/// resolver, redirect revalidation, hostname/IP blocklist,
938	/// `DYN_MM_ALLOW_INTERNAL` opt-in.
939	///
940	/// **Lifecycle:** `LazyLock` so the closure runs on first access. For MM-
941	/// countable or routable preprocessors, `OpenAIPreprocessor::new_with_parts` calls
942	/// `LazyLock::force(...)` at startup — that surfaces TLS-root / reqwest-
943	/// init / env-misconfig failures at deployment time, not on the first MM
944	/// request 20 minutes in. Text-only deployments skip the force, leaving
945	/// the LazyLock dormant.
946	#[cfg(feature = "mm-routing")]
947	static DIM_FETCH_MEDIA_FETCHER: std::sync::LazyLock<crate::preprocessor::media::MediaFetcher> =
948	    std::sync::LazyLock::new(crate::preprocessor::media::MediaFetcher::from_env);
949	
950	#[cfg(feature = "mm-routing")]
951	static DIM_FETCH_HTTP_CLIENT: std::sync::LazyLock<reqwest::Client> =
952	    std::sync::LazyLock::new(|| {
953	        DIM_FETCH_MEDIA_FETCHER
954	            .build_http_client()
955	            .expect("dim-fetch http client construction failed")
956	    });
