961	fn attach_agent_context_from_context(
962	    request: &mut PreprocessedRequest,
963	    context: &PipelineContext<()>,
964	) {
965	    if let Ok(agent_context) = context.get::<crate::protocols::common::extensions::AgentContext>(
966	        crate::protocols::common::extensions::AGENT_CONTEXT_CONTEXT_KEY,
967	    ) {
968	        request.agent_context = Some(agent_context.as_ref().clone());
969	    }
970	}
971	
972	/// Thin wrapper that normalizes `function.arguments` in historical tool-calls
973	/// from a JSON string to an object before passing messages to a MiniJinja
974	/// template.  Only used when `OpenAIPreprocessor::normalize_tool_call_args` is
975	/// true (e.g. GLM-5.2); all other trait methods delegate directly to the inner
976	/// request so routing, sampling, and annotation behavior is unchanged.
977	struct NormalizedArgsRequest<'a, R>(&'a R);
978	
979	impl<R: OAIChatLikeRequest> OAIChatLikeRequest for NormalizedArgsRequest<'_, R> {
980	    fn model(&self) -> String {
981	        self.0.model()
982	    }
983	
984	    fn messages(&self) -> minijinja::value::Value {
985	        let mut json =
986	            serde_json::to_value(self.0.typed_messages().unwrap_or_default()).unwrap_or_default();
987	        if let Err(e) = crate::preprocessor::prompt::normalize_tool_call_arguments(&mut json) {
988	            tracing::error!(
989	                error = %e,
990	                "tool_call arguments normalization failed; template rendering may fail \
991	                 if it calls .items() on a string"
992	            );
993	        }
994	        minijinja::value::Value::from_serialize(&json)
995	    }
996	
997	    fn typed_messages(&self) -> Option<&[dynamo_protocols::types::ChatCompletionRequestMessage]> {
998	        self.0.typed_messages()
999	    }
1000	
