387	        self.bytes_used = self.bytes_used.saturating_add(val_bytes);
388	        while self.bytes_used > self.budget_bytes && !self.lru.is_empty() {
389	            if let Some((_, old)) = self.lru.pop_lru() {
390	                self.bytes_used = self.bytes_used.saturating_sub(descriptor_bytes(&old));
391	            } else {
392	                break;
393	            }
394	        }
