513	    pub async fn fetch_and_decode_media_part(
514	        &self,
515	        oai_content_part: &ChatCompletionRequestUserMessageContentPart,
516	        media_io_kwargs: Option<&MediaDecoder>,
517	    ) -> Result<RdmaMediaDataDescriptor> {
518	        // Image-only fast path: cache lookup keyed by URL/datauri string.
519	        // Video/audio aren't cached yet (their lifetime/content semantics
520	        // are different — easy to add later if profiling justifies it).
521	        // The cache stores the post-decode + NIXL-registered descriptor;
522	        // a hit short-circuits both the network fetch and the image decode.
523	        if let (Some(cache), ChatCompletionRequestUserMessageContentPart::ImageUrl(image_part)) =
524	            (self.cache.as_ref(), oai_content_part)
525	        {
526	            // media_io_kwargs is per-request and could change the decode
527	            // output (resize, normalisation). When it's set we skip the
528	            // cache to stay correct; in practice it's None on the common
529	            // path so the hit rate is unaffected.
530	            if media_io_kwargs.is_none()
531	                && let Some(url) = image_part.image_url.as_ref().map(|media| &media.url)
532	            {
533	                let key = Self::cache_key(url.as_str());
534	                if let Some(hit) = cache.lock().get(&key) {
535	                    tracing::debug!(url_hash = key, "[mm-cache] hit");
536	                    return Ok(hit);
537	                }
538	            }
539	        }
540	
541	        // fetch the media, decode and NIXL-register
542	        let decoded = match oai_content_part {
543	            ChatCompletionRequestUserMessageContentPart::ImageUrl(image_part) => {
544	                let mdc_decoder = self
545	                    .media_decoder
546	                    .image
547	                    .as_ref()
548	                    .ok_or_else(|| anyhow::anyhow!("Model does not support image inputs"))?;
549	
550	                let url = require_image_url(image_part)?;
551	                self.media_fetcher
552	                    .check_if_url_allowed_with_dns(url)
553	                    .await?;
554	                let data = EncodedMediaData::from_url(url, &self.http_client)
555	                    .await
556	                    .map_err(MediaFetcher::map_fetch_error)?;
557	
558	                // Use runtime decoder if provided, with MDC limits enforced
559	                let decoder =
560	                    mdc_decoder.with_runtime(media_io_kwargs.and_then(|k| k.image.as_ref()));
561	                decoder.decode_async(data).await?
562	            }
563	            #[allow(unused_variables)]
564	            ChatCompletionRequestUserMessageContentPart::VideoUrl(video_part) => {
565	                #[cfg(not(feature = "media-ffmpeg"))]
566	                anyhow::bail!("Video decoding requires the 'media-ffmpeg' feature to be enabled");
567	
568	                #[cfg(feature = "media-ffmpeg")]
569	                {
570	                    let mdc_decoder =
571	                        self.media_decoder.video.as_ref().ok_or_else(|| {
572	                            anyhow::anyhow!("Model does not support video inputs")
573	                        })?;
574	
575	                    let url = video_part
576	                        .video_url
577	                        .as_ref()
578	                        .map(|media| &media.url)
579	                        .ok_or_else(|| {
580	                            anyhow::anyhow!("Cannot decode a video content part without a URL")
581	                        })?;
582	                    self.media_fetcher
583	                        .check_if_url_allowed_with_dns(url)
584	                        .await?;
585	                    let data = EncodedMediaData::from_url(url, &self.http_client)
586	                        .await
587	                        .map_err(MediaFetcher::map_fetch_error)?;
588	
589	                    // Use runtime decoder if provided, with MDC limits enforced
590	                    let decoder =
591	                        mdc_decoder.with_runtime(media_io_kwargs.and_then(|k| k.video.as_ref()));
592	                    decoder.decode_async(data).await?
593	                }
594	            }
595	            ChatCompletionRequestUserMessageContentPart::AudioUrl(_) => {
596	                anyhow::bail!("Audio decoding is not supported yet");
597	            }
598	            _ => anyhow::bail!("Unsupported media type"),
599	        };
600	
601	        let rdma_descriptor = decoded.into_rdma_descriptor(&self.nixl_agent)?;
602	
603	        // Insert into the cache on the way out. We only cache image inputs
604	        // (matched in the lookup above) and only when no per-request decoder
605	        // override is in effect. The descriptor is `Clone` and shares the
606	        // underlying NIXL registration via `Arc`, so the cached entry stays
607	        // alive across in-flight requests; eviction just drops the cache's
608	        // own reference.
609	        if let (Some(cache), ChatCompletionRequestUserMessageContentPart::ImageUrl(image_part)) =
610	            (self.cache.as_ref(), oai_content_part)
611	            && media_io_kwargs.is_none()
612	            && let Some(url) = image_part.image_url.as_ref().map(|media| &media.url)
613	        {
614	            let key = Self::cache_key(url.as_str());
615	            let bytes = descriptor_bytes(&rdma_descriptor);
616	            cache.lock().put(key, rdma_descriptor.clone());
617	            tracing::debug!(url_hash = key, bytes, "[mm-cache] insert");
618	        }
619	
620	        Ok(rdma_descriptor)
621	    }
622	}
