820	        // /a.png expects 2 hits: (i) cold insert, (ii) re-fetch after C
821	        // evicts A. /b.png expects 1: cold insert + a re-fetch served from
822	        // cache. /c.png expects 1: cold insert (it stays in cache too).
823	        let mock_a = server
824	            .mock("GET", "/a.png")
825	            .with_status(200)
826	            .with_header("content-type", "image/png")
827	            .with_body(&test_image_bytes[..])
828	            .expect(2)
829	            .create_async()
830	            .await;
