832	            .mock("GET", "/b.png")
833	            .with_status(200)
834	            .with_header("content-type", "image/png")
835	            .with_body(&test_image_bytes[..])
836	            .expect(1)
837	            .create_async()
838	            .await;
839	        let mock_c = server
840	            .mock("GET", "/c.png")
841	            .with_status(200)
842	            .with_header("content-type", "image/png")
843	            .with_body(&test_image_bytes[..])
844	            .expect(1)
845	            .create_async()
846	            .await;
847	
848	        let media_decoder = MediaDecoder {
849	            image: Some(ImageDecoder::default()),
850	            #[cfg(feature = "media-ffmpeg")]
851	            video: None,
852	        };
853	        let fetcher = MediaFetcher {
854	            allow_direct_ip: true,
855	            allow_direct_port: true,
856	            allow_private_ips: true,
857	            ..Default::default()
858	        };
859	
860	        // Single decoded image is ~8.57 MB (1125x1999x4 RGBA). Budget = 18 MB
861	        // accommodates exactly 2 entries; inserting a 3rd forces an eviction.
862	        let loader = match MediaLoader::with_cache_budget_bytes(
863	            media_decoder,
864	            Some(fetcher),
865	            18 * 1024 * 1024,
866	        ) {
867	            Ok(l) => l,
868	            Err(e) => {
869	                println!("test_cache_budget_lru_eviction ... ignored ({})", e);
870	                return;
871	            }
872	        };
873	
874	        let make_part = |path: &str| {
875	            let image_url = ImageUrl::from(format!("{}{}", server.url(), path));
876	            ChatCompletionRequestUserMessageContentPart::ImageUrl(
877	                ChatCompletionRequestMessageContentPartImage {
878	                    image_url: Some(image_url),
879	                    uuid: None,
880	                },
881	            )
882	        };
883	
884	        let part_a = make_part("/a.png");
885	        let part_b = make_part("/b.png");
886	        let part_c = make_part("/c.png");
887	
888	        // Cold-fetch A and B (cache: [B, A], B is MRU).
889	        for (label, part) in [("a", &part_a), ("b", &part_b)] {
890	            match loader.fetch_and_decode_media_part(part, None).await {
891	                Ok(_) => {}
892	                Err(e) if e.to_string().contains("NIXL agent is not available") => {
893	                    println!(
894	                        "test_cache_budget_lru_eviction ... ignored (NIXL not available, fetch={})",
895	                        label
896	                    );
897	                    return;
898	                }
899	                Err(e) => panic!("fetch {} failed: {}", label, e),
900	            }
901	        }
902	        assert_eq!(loader.cache_len(), 2);
903	
904	        // Touch B to make it the LRU front; A becomes the eviction target
905	        // when the next insert lands. mock_b expects 1 total hit, so this
906	        // must be served from cache.
907	        loader
908	            .fetch_and_decode_media_part(&part_b, None)
909	            .await
910	            .expect("b re-fetch should hit cache");
911	
912	        // Cold-fetch C → cache is full, evict A (LRU), now cache = {C, B}.
913	        loader
914	            .fetch_and_decode_media_part(&part_c, None)
915	            .await
916	            .expect("c cold fetch should succeed");
917	        assert_eq!(loader.cache_len(), 2);
918	
919	        // Re-fetching A should miss the cache (A was evicted), triggering a
920	        // second network GET — matched by mock_a.expect(2).
921	        loader
922	            .fetch_and_decode_media_part(&part_a, None)
923	            .await
924	            .expect("a re-fetch after eviction should succeed");
925	        assert_eq!(loader.cache_len(), 2);
926	
927	        mock_a.assert_async().await;
928	        mock_b.assert_async().await;
929	        mock_c.assert_async().await;
930	    }
